"""Reverse only approved MEMQ extensions, then compare complete baseline ASTs."""
import ast,copy,hashlib,json,runpy,sys
from pathlib import Path
R=Path(sys.argv[1]).resolve(); B=Path(sys.argv[2]).resolve(); O=Path(sys.argv[3])
v=runpy.run_path(str(R/'docs/planning/active/command-refactor/validation/memory-queries/verify_directive_corrections.py'))
def shape(x): return ast.dump(x,include_attributes=False)
def require(x,msg):
 if not x: raise RuntimeError(msg)
results={}
for file in ['test_diagnostics.py','test_session_views.py']:
 relative=Path('packages/friday-commands/tests_commands')/file
 current=ast.parse((R/relative).read_text()); old=ast.parse((B/relative).read_text())
 for i,n in enumerate(current.body):
  if isinstance(n,ast.FunctionDef):
   if n.name=='test_diagnostic_specs_exports_and_factory': current.body[i]=v['reverse_diagnostic'](n)
   elif n.name=='_check_closed_union_retains_old_variants_and_refuses_nested_values': current.body[i]=v['reverse_union'](n)
   elif n.name=='test_session_specs_and_factory_are_immutable': v['remove_names'](v['api_literal'](n),v['ADDITIONS'])
 require(shape(current)==shape(old),'old test AST drift '+file)
 results[file]='complete module AST equals baseline after exact reversal'
relative=Path('packages/friday-commands/src/friday_commands/contracts.py')
current=ast.parse((R/relative).read_text()); old=ast.parse((B/relative).read_text())
current.body=[n for n in current.body if not(isinstance(n,ast.ClassDef) and n.name in v['MODELS']) and not(isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='MemoryRecordKindName' for t in n.targets))]
def union_members(n):
 return union_members(n.left)+union_members(n.right) if isinstance(n,ast.BinOp) and isinstance(n.op,ast.BitOr) else [n]
for n in current.body:
 if isinstance(n,ast.TypeAlias) and n.name.id=='FoundationData':
  members=union_members(n.value); require([x.id for x in members[-6:]]==list(v['OUTCOMES']),'union appended order')
  n.value=members[0]
  for part in members[1:-6]: n.value=ast.BinOp(left=n.value,op=ast.BitOr(),right=part)
 if isinstance(n,ast.ClassDef) and n.name=='CommandOutcome':
  whitelist=next(x for x in ast.walk(n) if isinstance(x,ast.Tuple) and len(x.elts)==18 and all(isinstance(e,ast.Name) for e in x.elts))
  require([x.id for x in whitelist.elts[-6:]]==list(v['OUTCOMES']),'whitelist order'); del whitelist.elts[-6:]
require(shape(current)==shape(old),'old contracts AST drift')
results['contracts.py']='baseline AST after removing alias,13 models,six union/whitelist entries'
relative=Path('packages/friday-commands/src/friday_commands/__init__.py')
current=ast.parse((R/relative).read_text()); old=ast.parse((B/relative).read_text())
current.body=[n for n in current.body if not(isinstance(n,ast.ImportFrom) and n.module=='memory_queries')]
for n in current.body:
 if isinstance(n,ast.ImportFrom) and n.module=='contracts': n.names=[x for x in n.names if x.name not in v['MODELS']]
 if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='__all__' for t in n.targets): v['remove_names'](n.value,v['ADDITIONS'])
require(shape(current)==shape(old),'old API imports/order drift')
results['__init__.py']='original imports and ordered38 exports preserved'
fixture=R/'packages/friday-commands/tests_commands/fixtures/memory-query-metadata.json'
require(hashlib.sha256(fixture.read_bytes()).hexdigest()=='a2b848e67b1ee033e22d22a5e1c96a672979e674f5b1ec0fd9e82f6f7aee6480','fixture bytes')
results['fixture']='exact approved preparation bytes'
O.write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2))

import hashlib,json,sys
from pathlib import Path
source=Path(sys.argv[1]).resolve(); destination=Path(sys.argv[2]); selectors=sys.argv[3:]
sys.path.insert(0,str(source/'src'))
import friday_commands
import pytest
snapshots={}; calls=[]
def snapshot(stage):
 rows={}
 for name,module in list(sys.modules.items()):
  if name=='friday_commands' or name.startswith('friday_commands.'):
   p=Path(module.__file__).resolve()
   if not p.is_relative_to(source/'src/friday_commands'): raise RuntimeError('Wrong canonical origin: '+str(p))
   rows[name]={'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 snapshots[stage]=rows
snapshot('before_pytest')
class Evidence:
 def pytest_runtest_logreport(self,report):
  if report.failed:
   calls.append({'node':report.nodeid,'when':report.when,'failure':str(report.longrepr)})
 def pytest_sessionfinish(self,session,exitstatus): snapshot('session_finish')
code=pytest.main(['-p','no:cacheprovider','-q','--basetemp',str(destination.parent/'pytest-launch-tmp'/destination.stem),*selectors],plugins=[Evidence()])
snapshot('after_pytest')
destination.write_text(json.dumps({'exit':int(code),'origins':snapshots,'failures':calls},indent=2)+'\n')
raise SystemExit(code)

